     */
    public function validateCurrentPtrs(string|array $domains): array
    {
        /** @var ValidateCurrentPtrsResult $result Validated against MailSpec::VALIDATE_CURRENT_PTRS. */
        $result = ($this->run)(MailSpec::VALIDATE_CURRENT_PTRS, ['domains' => $domains]);

        return $result;
    }

